package cn.iocoder.yudao.module.zsjos.service.studentops; import cn.iocoder.yudao.module.zsjos.dal.mysql.studentops.ExceptionTicketMapper; import cn.iocoder.yudao.module.zsjos.framework.permission.ZsjosObjectPermissionProvider; import jakarta.annotation.Resource; import org.springframework.stereotype.Component; import java.util.Objects; @Component public class ExceptionObjectPermissionProvider implements ZsjosObjectPermissionProvider{@Resource private ExceptionTicketMapper mapper;public String getBizType(){return "media-exception";}public boolean hasPermission(Long id,String action,Long uid){var x=mapper.selectById(id);return x!=null&&Objects.equals(x.getOwnerUserId(),uid);}}
